sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  let title = {};
  let subHeadings = [];

  title.label = 
    api.data.Group_Manager.results[0].manager._reference.title.displayValue || "No title available";
	subHeadings.push(title);
  return subHeadings;
}
